import { EditorView } from '@codemirror/view';
import { type ReactNode, type RefObject } from 'react';

import { type IconName } from '@grafana/data';
import { t } from '@grafana/i18n';
import { Stack, ToolbarButton } from '@grafana/ui';

import { TextMode } from '../../panelcfg.gen';
import { isTextNewFeaturesEnabled } from '../utils';

import { insertAtCursor, toggleLinePrefix, toggleOrderedList, toggleSurround } from './editorCommands';

const MARKDOWN_TABLE_SNIPPET = '\n| Column | Column |\n| ------ | ------ |\n| Value  | Value  |\n';
const HTML_TABLE_SNIPPET =
  '\n<table>\n  <tr>\n    <th>Column</th>\n    <th>Column</th>\n  </tr>\n  <tr>\n    <td>Value</td>\n    <td>Value</td>\n  </tr>\n</table>\n';
const DIAGRAM_BODY = 'graph TD\n  A[Start] --> B[End]\n';
const MARKDOWN_DIAGRAM_SNIPPET = `\n\`\`\`mermaid\n${DIAGRAM_BODY}\`\`\`\n`;
const HTML_DIAGRAM_SNIPPET = `\n<pre class="mermaid">\n${DIAGRAM_BODY}</pre>\n`;

export const FORMAT_TOOLBAR_TEST_ID = 'TextNGEditor-format-toolbar';

interface FormatAction {
  key: string;
  tooltip: string;
  icon?: IconName;
  label?: ReactNode;
  run: (view: EditorView) => void;
}

/** Spread into `toggleSurround`. */
type Markers = readonly [before: string, after?: string];

interface InlineMarkers {
  bold: Markers;
  italic: Markers;
  link: Markers;
}

const MARKDOWN_MARKERS: InlineMarkers = {
  bold: ['**'],
  italic: ['*'],
  link: ['[', '](https://)'],
};

const HTML_MARKERS: InlineMarkers = {
  bold: ['<b>', '</b>'],
  italic: ['<i>', '</i>'],
  link: ['<a href="https://">', '</a>'],
};

function getFormatActions(mode: TextMode): FormatAction[] {
  if (mode === TextMode.Code) {
    return [];
  }

  const isHtml = mode === TextMode.HTML;
  const markers = isHtml ? HTML_MARKERS : MARKDOWN_MARKERS;

  const heading: FormatAction = {
    key: 'heading',
    tooltip: t('textng.editor.tooltip-heading', 'Heading'),
    label: t('textng.editor.format-heading', 'H'),
    run: (view) => (isHtml ? toggleSurround(view, '<h1>', '</h1>') : toggleLinePrefix(view, '# ')),
  };

  const inlineActions: FormatAction[] = [
    {
      key: 'bold',
      tooltip: t('textng.editor.tooltip-bold', 'Bold'),
      label: <strong>{t('textng.editor.format-bold', 'B')}</strong>,
      run: (view) => toggleSurround(view, ...markers.bold),
    },
    {
      key: 'italic',
      tooltip: t('textng.editor.tooltip-italic', 'Italic'),
      label: <em>{t('textng.editor.format-italic', 'I')}</em>,
      run: (view) => toggleSurround(view, ...markers.italic),
    },
    {
      key: 'link',
      tooltip: t('textng.editor.tooltip-link', 'Link'),
      icon: 'link',
      run: (view) => toggleSurround(view, ...markers.link),
    },
  ];

  const table: FormatAction = {
    key: 'table',
    tooltip: t('textng.editor.tooltip-table', 'Table'),
    icon: 'table',
    run: (view) => insertAtCursor(view, isHtml ? HTML_TABLE_SNIPPET : MARKDOWN_TABLE_SNIPPET),
  };

  const diagramAction: FormatAction[] = isTextNewFeaturesEnabled()
    ? [
        {
          key: 'diagram',
          tooltip: t('textng.editor.tooltip-diagram', 'Mermaid diagram'),
          icon: 'code-branch',
          run: (view) => insertAtCursor(view, isHtml ? HTML_DIAGRAM_SNIPPET : MARKDOWN_DIAGRAM_SNIPPET),
        },
      ]
    : [];

  const insertVariable: FormatAction = {
    key: 'variable',
    tooltip: t('textng.editor.tooltip-insert-variable', 'Insert variable'),
    icon: 'brackets-curly',
    run: (view) => insertAtCursor(view, '${}'),
  };

  if (isHtml) {
    return [heading, ...inlineActions, table, ...diagramAction, insertVariable];
  }

  // Markdown only
  return [
    heading,
    ...inlineActions,
    {
      key: 'bullet-list',
      tooltip: t('textng.editor.tooltip-bullet-list', 'Bullet list'),
      icon: 'list-ul',
      run: (view) => toggleLinePrefix(view, '- '),
    },
    {
      key: 'numbered-list',
      tooltip: t('textng.editor.tooltip-numbered-list', 'Numbered list'),
      icon: 'list-ol',
      run: (view) => toggleOrderedList(view),
    },
    {
      key: 'checklist',
      tooltip: t('textng.editor.tooltip-checklist', 'Checklist'),
      icon: 'check-square',
      run: (view) => toggleLinePrefix(view, '- [ ] '),
    },
    table,
    ...diagramAction,
    insertVariable,
  ];
}

export interface TextNGFormatToolbarProps {
  mode: TextMode;
  /**
   * Wrapper the CodeMirror editor is mounted into. The lazily-loaded bundle does
   * not expose its `EditorView`, so it is looked up from this container's DOM.
   */
  editorContainerRef: RefObject<HTMLDivElement | null>;
}

export function TextNGFormatToolbar({ mode, editorContainerRef }: TextNGFormatToolbarProps) {
  const actions = getFormatActions(mode);

  if (actions.length === 0) {
    return null;
  }

  const runAction = (action: FormatAction) => {
    const container = editorContainerRef.current;
    const view = container ? EditorView.findFromDOM(container) : null;
    if (view) {
      action.run(view);
    }
  };

  return (
    <Stack gap={0.5} wrap="wrap" alignItems="center" data-testid={FORMAT_TOOLBAR_TEST_ID}>
      {actions.map((action) => (
        <ToolbarButton key={action.key} icon={action.icon} tooltip={action.tooltip} onClick={() => runAction(action)}>
          {action.label}
        </ToolbarButton>
      ))}
    </Stack>
  );
}
